// DELEGATION: forwards selected methods, hides others, adds logic
package com.bank.delegation.service;

import com.bank.delegation.delegate.AccountOperations;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

public class SavingsService {
    private final AccountOperations delegate;  // HAS-A delegate
    private final List<String> auditLog = new ArrayList<>();
    private static final BigDecimal MIN_BALANCE = new BigDecimal("1000");

    public SavingsService(AccountOperations delegate) {
        this.delegate = delegate;
    }

    // FORWARD with added validation + logging:
    public void deposit(BigDecimal amount) {
        auditLog.add("DEPOSIT attempt: Rs." + amount);
        delegate.deposit(amount);  // DELEGATE
        auditLog.add("DEPOSIT success: balance Rs." + delegate.getBalance());
    }

    // FORWARD with minimum balance check:
    public void withdraw(BigDecimal amount) {
        BigDecimal remaining = delegate.getBalance().subtract(amount);
        if (remaining.compareTo(MIN_BALANCE) < 0) {
            throw new IllegalStateException("Must maintain Rs." + MIN_BALANCE + " minimum");
        }
        auditLog.add("WITHDRAW attempt: Rs." + amount);
        delegate.withdraw(amount);  // DELEGATE
    }

    // FORWARD: read-only
    public BigDecimal getBalance() { return delegate.getBalance(); }

    // NOT FORWARDED: transferInternational — DELIBERATELY HIDDEN!
    // NOT FORWARDED: closeAccount — DELIBERATELY HIDDEN!
    // savingsService.transferInternational() → COMPILE ERROR! Method doesn't exist!

    public List<String> getAuditLog() { return List.copyOf(auditLog); }
}
