// ─── File: src/test/java/com/bank/delegation/DelegationTest.java ───
package com.bank.delegation;

import com.bank.delegation.delegate.AccountOperations;
import com.bank.delegation.service.SavingsService;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class DelegationTest {

    @Test
    void delegation_forwardsDeposit() {
        AccountOperations ops = new AccountOperations(new BigDecimal("10000"));
        SavingsService service = new SavingsService(ops);
        service.deposit(new BigDecimal("5000"));
        assertThat(service.getBalance()).isEqualByComparingTo("15000");
    }

    @Test
    void delegation_addsValidationAroundWithdraw() {
        AccountOperations ops = new AccountOperations(new BigDecimal("5000"));
        SavingsService service = new SavingsService(ops);
        assertThatThrownBy(() -> service.withdraw(new BigDecimal("4500")))
            .hasMessageContaining("minimum");
        // delegate.withdraw would succeed (5000-4500=500 > 0)
        // but SavingsService adds minimum balance check BEFORE delegating!
    }

    @Test
    void delegation_hidesUnwantedMethods() {
        SavingsService service = new SavingsService(new AccountOperations(BigDecimal.ZERO));
        // service.transferInternational(...)  → COMPILE ERROR! Method doesn't exist!
        // service.closeAccount()              → COMPILE ERROR! Method doesn't exist!
        // These methods exist on AccountOperations but SavingsService doesn't forward them.
        assertThat(true).isTrue();
    }

    @Test
    void delegation_addsAuditLogging() {
        AccountOperations ops = new AccountOperations(new BigDecimal("10000"));
        SavingsService service = new SavingsService(ops);
        service.deposit(new BigDecimal("5000"));
        assertThat(service.getAuditLog()).hasSize(2);
        assertThat(service.getAuditLog().get(0)).contains("DEPOSIT attempt");
        // Audit logging added AROUND the delegation — not in the delegate itself.
    }

    @Test
    void delegation_canSwapDelegate() {
        AccountOperations prodOps = new AccountOperations(new BigDecimal("100000"));
        AccountOperations testOps = new AccountOperations(BigDecimal.ZERO);

        SavingsService prodService = new SavingsService(prodOps);
        SavingsService testService = new SavingsService(testOps);

        assertThat(prodService.getBalance()).isEqualByComparingTo("100000");
        assertThat(testService.getBalance()).isEqualByComparingTo("0");
        // Same SavingsService class, different delegates — runtime flexibility!
    }

    @Test
    void delegation_vsInheritance() {
        // INHERITANCE: SavingsAccount extends Account
        //   → transferInternational() EXPOSED (unwanted!)
        //   → can't add min balance check without fragile super.withdraw()
        //   → can't swap Account implementation at runtime

        // DELEGATION: SavingsService has-a AccountOperations
        //   → transferInternational() HIDDEN (not forwarded!)
        //   → min balance check added BEFORE delegate.withdraw()
        //   → swap delegate: new SavingsService(mockOps) for testing

        assertThat(true).isTrue();
    }
}
